fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cell: i32 = 64;
    let cols: i32 = w / cell;
    let rows: i32 = h / cell;
    let gen: i32 = t / 120;
    let mut r: i32 = 0;
    while r < rows {
        let mut c: i32 = 0;
        while c < cols {
            let mut hsh: i32 = gen * 7 + r * 7919 + c * 104729;
            hsh = hsh * 1103515245 + 12345;
            let o: i32 = (hsh >> 16) & 3;
            let x: i32 = c * cell;
            let y: i32 = r * cell;
            let bg: i32 = if ((r + c) & 1) == 0 { 0xf2e8da } else { 0xe8d8c3 };
            let fg: i32 = if ((r + c) & 1) == 0 { 0x9a3b3b } else { 0x2f5d62 };
            host::display::fill_rect(x, y, cell, cell, bg);
            if o == 0 {
                host::display::fill_triangle(x, y, x + cell - 1, y, x, y + cell - 1, fg);
            } else if o == 1 {
                host::display::fill_triangle(x, y, x + cell - 1, y, x + cell - 1, y + cell - 1, fg);
            } else if o == 2 {
                host::display::fill_triangle(x + cell - 1, y, x + cell - 1, y + cell - 1, x, y + cell - 1, fg);
            } else {
                host::display::fill_triangle(x, y, x + cell - 1, y + cell - 1, x, y + cell - 1, fg);
            }
            c = c + 1;
        }
        r = r + 1;
    }
    host::display::present();
}
